fixedSource: |
  using System.Runtime.CompilerServices;

  WeakReference closedWindow = OpenAndCloseWindow();
  GC.Collect();
  GC.WaitForPendingFinalizers();
  GC.Collect();
  Console.WriteLine(closedWindow.IsAlive);

  [MethodImpl(MethodImplOptions.NoInlining)]
  static WeakReference OpenAndCloseWindow()
  {
      ReportWindow window = new ReportWindow();
      window.Close();
      return new WeakReference(window);
  }

  static class AppSettings
  {
      public static event EventHandler Changed;

      public static void NotifyChanged() => Changed?.Invoke(null, EventArgs.Empty);
  }

  class ReportWindow
  {
      public bool IsOpen { get; private set; } = true;
      public int RefreshCount { get; private set; }

      public ReportWindow()
      {
          AppSettings.Changed += OnSettingsChanged;
      }

      public void Close()
      {
          IsOpen = false;
          AppSettings.Changed -= OnSettingsChanged;
      }

      private void OnSettingsChanged(object sender, EventArgs e) => RefreshCount++;
  }
fixedExpect: { kind: output, value: "False" }
